<script lang="ts">
	import { boxWith } from "svelte-toolbelt";
	import type { PresenceLayerImplProps } from "./types.js";
	import { Presence } from "./presence.svelte.js";

	let { open, forceMount, presence, ref }: PresenceLayerImplProps = $props();

	const presencpens = new Presence({
		open: boxWith(() => open),
		ref,
	});
</script>

{#if forceMount || open || presencpens.isPresent}
	{@render presence?.({
		present: presencpens.isPresent,
		transitionStatus: presencpens.transitionStatus,
	})}
{/if}
